function setFeedbackStatus(text,kind=''){const e=$('feedbackStatus');e.textContent=text||'';e.className=`small feedback-status ${kind||''}`;}
async function openExternal(url){if(!url)return false;try{await chrome.tabs.create({url});return true;}catch{return false;}}
function issueBaseUrl(repo){try{const u=new URL(repo);if(u.hostname!=='github.com')return null;return u.href.replace(/\/$/,'')+'/issues/new';}catch{return null;}}
async function reportProblem(){try{const report=await publicBugReportText();await navigator.clipboard.writeText(report);const repo=feedbackLinks().githubRepoUrl,base=issueBaseUrl(repo);if(!base){setFeedbackStatus(tr('reportCopiedNoLink'),'ok');return;}const browser=browserIdentity(),site=currentStatus?.site?.name||SITE_API.siteForUrl(activeTab?.url||'')?.name||'Web';const url=new URL(base);url.searchParams.set('title',`[Bug] ${site} — DoneBell ${chrome.runtime.getManifest().version}`);url.searchParams.set('body',`${tr('githubBugBody')}\n\n**DoneBell:** ${chrome.runtime.getManifest().version}\n**Browser:** ${browser.name} ${browser.version}\n**Site:** ${site}\n\n${tr('githubPasteDiagnostics')}`);await openExternal(url.href);setFeedbackStatus(tr('reportCopiedOpened'),'ok');}catch(e){setFeedbackStatus(String(e),'bad');}}
async function suggestIdea(){const base=issueBaseUrl(feedbackLinks().githubRepoUrl);if(!base){setFeedbackStatus(tr('feedbackLinkMissing'),'bad');return;}const url=new URL(base);url.searchParams.set('title','[Feature] ');url.searchParams.set('body',tr('githubFeatureBody'));await openExternal(url.href);}
async function supportDoneBell(){const url=feedbackLinks().supportUrl;if(!url){setFeedbackStatus(tr('supportLinkMissing'),'bad');return;}await openExternal(url);}
function refreshFeedbackAvailability(){const l=feedbackLinks();const support=$('supportDoneBell');support.hidden=!l.supportUrl;const repoOk=Boolean(issueBaseUrl(l.githubRepoUrl));$('reportProblem').classList.toggle('feedback-disabled',!repoOk);$('suggestIdea').classList.toggle('feedback-disabled',!repoOk);$('reportProblem').title=repoOk?'':tr('feedbackLinkMissing');$('suggestIdea').title=repoOk?'':tr('feedbackLinkMissing');}

function playerModeLabel(mode){return tr(mode==='repeat-all'?'playerModeRepeatAll':mode==='repeat-one'?'playerModeRepeatOne':'playerModeShuffle');}
function playerModeIcon(mode){return mode==='repeat-all'?'🔁':mode==='repeat-one'?'🔂':'🔀';}
let playerSeekDuration=0;
let playerSeekDragging=false;
function formatPlayerTime(value){
  const total=Math.max(0,Math.floor(Number(value)||0)),h=Math.floor(total/3600),m=Math.floor((total%3600)/60),s=total%60;
  return h?`${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${m}:${String(s).padStart(2,'0')}`;
}
function previewPlayerSeek(){
  if(!playerSeekDuration)return;
  $('playerCurrentTime').textContent=formatPlayerTime(playerSeekDuration*(Number($('playerSeek').value)||0)/1000);
}
async function commitPlayerSeek(){
  if(!playerSeekDuration){playerSeekDragging=false;return;}
  const position=playerSeekDuration*(Number($('playerSeek').value)||0)/1000;
  const r=await chrome.runtime.sendMessage({type:'seek-audio',position});
  if(r?.ok===false)setSoundMessage(r.error||'Seek unavailable','warn');
  playerSeekDragging=false;
  setTimeout(refreshNowPlaying,60);
}
async function refreshNowPlaying(){
  try{
    const r=await chrome.runtime.sendMessage({type:'get-player-state'}),s=r?.state||{},pl=r?.player||{};
    $('nowPlayingName').textContent=s.playing?(s.trackName||'Audio'):tr('nowPlayingIdle');
    $('nowPlayingMeta').textContent=s.playing?[s.siteId||'',s.audioScope||'',s.paused?'paused':''].filter(Boolean).join(' · '):'';
    $('playerPosition').textContent=pl.active&&pl.index?`${pl.index}/${pl.total||pl.trackCount||0}`:(pl.trackCount?`${pl.trackCount} tracks`:'');
    $('pauseResumeAudio').disabled=!s.playing&&!pl.trackCount;
    $('pauseResumeAudio').textContent=s.playing?(s.paused?'▶':'⏸'):'▶';
    $('pauseResumeAudio').title=s.playing?(s.paused?tr('resumeAudio'):tr('pauseAudio')):tr('playPlaylist');
    $('previousAudio').disabled=!pl.trackCount;
    $('nextAudio').disabled=!pl.trackCount;
    $('nowPlayingStop').disabled=!s.playing&&!pl.active;
    $('nowPlayingStop').textContent='■';
    $('nowPlayingStop').title=tr('stopAudio');
    $('playPlaylist').disabled=!pl.trackCount;
    $('playPlaylist').textContent=`▶ ${tr('playPlaylist')}`;
    $('playerModeCycle').textContent=playerModeIcon(pl.mode);
    $('playerModeCycle').title=playerModeLabel(pl.mode);
    $('playerModeText').textContent=tr('playerModeHint',{mode:playerModeLabel(pl.mode)});
    playerSeekDuration=Number(s.duration)||0;
    const playerPositionSeconds=Number(s.position)||0;
    $('playerSeek').disabled=!s.seekable||playerSeekDuration<=0;
    if(!playerSeekDragging){
      $('playerSeek').value=playerSeekDuration>0?String(Math.max(0,Math.min(1000,Math.round(playerPositionSeconds/playerSeekDuration*1000)))):'0';
      $('playerCurrentTime').textContent=formatPlayerTime(playerPositionSeconds);
    }
    $('playerDuration').textContent=formatPlayerTime(playerSeekDuration);
    $('playerSeek').title=tr('playerSeek');
    if(Number.isFinite(Number(s.volume))){
      const v=Math.round(Number(s.volume)*100);
      $('playerVolume').value=String(v);$('playerVolumeText').textContent=`${v}%`;
    }
  }catch{
    $('nowPlayingName').textContent=tr('nowPlayingIdle');
  }
}
async function previousAudio(){const r=await chrome.runtime.sendMessage({type:'player-previous'});if(r?.ok===false)setSoundMessage(r.error||tr('playerNoTracks'),'warn');setTimeout(refreshNowPlaying,100);}
async function stopPlayer(){await chrome.runtime.sendMessage({type:'player-stop'});setTimeout(refreshNowPlaying,70);}
async function cyclePlayerMode(){
  const r=await chrome.runtime.sendMessage({type:'get-player-state'}),m=r?.player?.mode||'shuffle';
  const next=m==='shuffle'?'repeat-all':m==='repeat-all'?'repeat-one':'shuffle';
  await chrome.runtime.sendMessage({type:'player-set-mode',mode:next});
  await refreshNowPlaying();
}
async function savePlayerVolume(){
  const v=Math.max(0,Math.min(100,Number($('playerVolume').value)||0));
  $('playerVolumeText').textContent=`${v}%`;
  $('volume').value=String(v);$('volumeText').textContent=`${v}%`;
  await chrome.storage.local.set({soundVolume:v/100});
  try{await chrome.runtime.sendMessage({type:'set-live-volume',volume:v/100});}catch{}
}

async function pauseResumeAudio(){
  // The top Play/Pause button belongs to the full playlist player.
  // If nothing is playing, player-toggle starts/resumes the player session.
  const r=await chrome.runtime.sendMessage({type:'player-toggle'});
  if(r?.ok===false)setSoundMessage(r.error||tr('playerNoTracks'),'warn');
  setTimeout(refreshNowPlaying,100);
}
async function playPlaylist(){
  // Explicitly start a fresh playlist session. This is intentionally independent
  // of any previous browser/session state, so it works after a browser reboot.
  const r=await chrome.runtime.sendMessage({type:'player-start'});
  if(r?.ok===false)setSoundMessage(r.error||tr('playerNoTracks'),'warn');
  setTimeout(refreshNowPlaying,120);
}
async function nextAudio(){
  const r=await chrome.runtime.sendMessage({type:'player-next'});
  if(r?.ok===false)setSoundMessage(r.error||tr('playerNoTracks'),'warn');
  setTimeout(refreshNowPlaying,100);
}

function downloadJson(name,obj){const u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
